/**
 * The dashboard's device keys: an Ed25519 signing key and an X25519 exchange key
 * generated by WebCrypto as non-extractable `CryptoKey`s. The private halves
 * never exist as bytes in JavaScript; IndexedDB stores the key objects
 * themselves (structured clone keeps them non-extractable). Only the public
 * keys are exported, to build the device record.
 */
import { b64encode, deviceIdFromSignPub, type DeviceKx, type DeviceSigner } from '@ak-vault/protocol';
import { AppError } from '../app-error.js';

export interface DeviceKeyMaterial {
  /** Ed25519 private key, `sign` only, non-extractable. */
  signKey: CryptoKey;
  /** X25519 private key, `deriveBits` only, non-extractable. */
  kxKey: CryptoKey;
  signPub: Uint8Array;
  kxPub: Uint8Array;
}

/** Copy into a fresh ArrayBuffer-backed view (what WebCrypto's BufferSource accepts). */
function buf(bytes: Uint8Array): Uint8Array<ArrayBuffer> {
  return new Uint8Array(bytes);
}

/** Generate both device keys. `unsupported_browser` when WebCrypto lacks Ed25519 or X25519. */
export async function generateDeviceKeys(subtle: SubtleCrypto = crypto.subtle): Promise<DeviceKeyMaterial> {
  let sign: CryptoKeyPair;
  let kx: CryptoKeyPair;
  try {
    sign = (await subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair;
    kx = (await subtle.generateKey({ name: 'X25519' }, false, ['deriveBits'])) as CryptoKeyPair;
  } catch {
    throw new AppError('unsupported_browser');
  }
  if (sign.privateKey.extractable || kx.privateKey.extractable) throw new AppError('unsupported_browser');
  const signPub = new Uint8Array(await subtle.exportKey('raw', sign.publicKey));
  const kxPub = new Uint8Array(await subtle.exportKey('raw', kx.publicKey));
  if (signPub.length !== 32 || kxPub.length !== 32) throw new AppError('unsupported_browser');
  return { signKey: sign.privateKey, kxKey: kx.privateKey, signPub, kxPub };
}

/** Whether a stored value is usable key material (IndexedDB data is not trusted blindly). */
export function isDeviceKeyMaterial(value: unknown): value is DeviceKeyMaterial {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  const isKey = (k: unknown, alg: string, usage: KeyUsage): boolean =>
    typeof CryptoKey !== 'undefined' && k instanceof CryptoKey && k.type === 'private' && !k.extractable && k.algorithm.name === alg && k.usages.includes(usage);
  const is32 = (b: unknown): boolean => b instanceof Uint8Array && b.length === 32;
  return isKey(v['signKey'], 'Ed25519', 'sign') && isKey(v['kxKey'], 'X25519', 'deriveBits') && is32(v['signPub']) && is32(v['kxPub']);
}

export function deviceIdOf(keys: DeviceKeyMaterial): string {
  return deviceIdFromSignPub(keys.signPub);
}

export function signPubB64(keys: DeviceKeyMaterial): string {
  return b64encode(keys.signPub);
}

export function kxPubB64(keys: DeviceKeyMaterial): string {
  return b64encode(keys.kxPub);
}

export function deviceSigner(keys: DeviceKeyMaterial, subtle: SubtleCrypto = crypto.subtle): DeviceSigner {
  return {
    async sign(message: Uint8Array): Promise<Uint8Array> {
      return new Uint8Array(await subtle.sign({ name: 'Ed25519' }, keys.signKey, buf(message)));
    },
  };
}

export function deviceKx(keys: DeviceKeyMaterial, subtle: SubtleCrypto = crypto.subtle): DeviceKx {
  return {
    kxPub: keys.kxPub,
    async deriveShared(peerPublic: Uint8Array): Promise<Uint8Array> {
      const peer = await subtle.importKey('raw', buf(peerPublic), { name: 'X25519' }, false, []);
      return new Uint8Array(await subtle.deriveBits({ name: 'X25519', public: peer }, keys.kxKey, 256));
    },
  };
}
